import { useState } from "react";
import { useNavigate } from "react-router-dom";

function Login() {
  const navigate = useNavigate();

  const [form, setForm] = useState({
    email: "",
    password: "",
  });

  const [showPassword, setShowPassword] = useState(false);

  const handleChange = (e) => {
    setForm({
      ...form,
      [e.target.name]: e.target.value,
    });
  };

  const handleLogin = (e) => {
    e.preventDefault();

    fetch("http://localhost:8080/api/login", {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
      },
      body: JSON.stringify(form),
    })
      .then((res) => res.json())
      .then((data) => {
        localStorage.setItem("user", JSON.stringify(data));
        alert("Login Successful!");
        navigate("/");
      })
      .catch(() => alert("Login Failed"));
  };

  return (
    <div className="min-h-screen flex bg-gradient-to-br from-black via-gray-900 to-gray-800">

      {/* LEFT SIDE HERO */}
      <div className="hidden md:flex w-1/2 relative items-center justify-center">
        <div className="absolute inset-0 bg-[url('https://images.unsplash.com/photo-1521737604893-d14cc237f11d')] bg-cover bg-center opacity-40"></div>
        <div className="relative text-white text-center px-10">
          <h1 className="text-5xl font-bold tracking-widest">LUXE</h1>
          <p className="mt-4 text-lg text-gray-200">The Essence of Slow Living</p>
        </div>
      </div>

      {/* RIGHT SIDE FORM */}
      <div className="w-full md:w-1/2 flex items-center justify-center p-6">

        <div className="w-full max-w-md bg-white/10 backdrop-blur-2xl border border-white/20 rounded-2xl p-10 shadow-2xl">

          {/* HEADER */}
          <div className="text-center mb-8">
            <h2 className="text-3xl font-bold text-white">Welcome Back</h2>
            <p className="text-gray-300 mt-2">Login to your account</p>
          </div>

          {/* FORM */}
          <form onSubmit={handleLogin} className="space-y-6">

            {/* EMAIL */}
            <div>
              <label className="text-sm text-gray-300">Email</label>
              <input
                type="email"
                name="email"
                placeholder="name@domain.com"
                value={form.email}
                onChange={handleChange}
                className="w-full mt-2 px-4 py-3 rounded-lg bg-white/10 border border-white/20 text-white placeholder-gray-400 focus:outline-none focus:ring-2 focus:ring-white/30"
                required
              />
            </div>

            {/* PASSWORD */}
            <div>
              <label className="text-sm text-gray-300">Password</label>

              <div className="relative mt-2">
                <input
                  type={showPassword ? "text" : "password"}
                  name="password"
                  value={form.password}
                  onChange={handleChange}
                  placeholder="••••••••"
                  className="w-full px-4 py-3 rounded-lg bg-white/10 border border-white/20 text-white placeholder-gray-400 focus:outline-none focus:ring-2 focus:ring-white/30"
                  required
                />

                <button
                  type="button"
                  onClick={() => setShowPassword(!showPassword)}
                  className="absolute right-3 top-3 text-gray-300 hover:text-white"
                >
                  👁
                </button>
              </div>
            </div>

            {/* BUTTON */}
            <button
              type="submit"
              className="w-full py-3 rounded-lg bg-white text-black font-semibold hover:bg-gray-200 transition"
            >
              Login
            </button>
          </form>

          {/* DIVIDER */}
          <div className="flex items-center my-6">
            <div className="flex-grow h-px bg-white/20"></div>
            <span className="mx-3 text-xs text-gray-300">OR</span>
            <div className="flex-grow h-px bg-white/20"></div>
          </div>

          {/* SOCIAL */}
          <div className="grid grid-cols-2 gap-3">
            <button className="py-2 rounded-lg border border-white/20 text-white hover:bg-white/10 transition">
              Google
            </button>
            <button className="py-2 rounded-lg border border-white/20 text-white hover:bg-white/10 transition">
              Apple
            </button>
          </div>

          {/* REGISTER */}
          <p className="text-center text-sm mt-6 text-gray-300">
            Don’t have an account?{" "}
            <span
              onClick={() => navigate("/register")}
              className="text-white font-semibold cursor-pointer hover:underline"
            >
              Sign Up
            </span>
          </p>
        </div>
      </div>
    </div>
  );
}

export default Login;
